    public function find(string $slug): Challenge
    {
        foreach ($this->all() as $challenge) {
            if ($challenge->slug === $slug) {
                return $challenge;
            }
        }
        throw new InvalidArgumentException('Неизвестное задание: ' . $slug);
    }

    /**
     * @param list<string> $goals
     * @param array<string, mixed>|string $body
     * @param list<string> $hints
     */
    private function challenge(int $number, string $slug, string $title, string $module, string $difficulty, int $minutes, string $category, string $summary, string $mission, array $goals, string $method, string $path, array|string $body, array $hints): Challenge
    {
        return new Challenge($number, $slug, $title, $module, $difficulty, $minutes, $category, $summary, $mission, 'Работайте только с виртуальными адресами стенда; данные и секреты учебные.', $goals, $hints, ['method' => $method, 'path' => $path, 'headers' => [], 'body' => $body, 'mode' => 'single']);
    }
